# Browser end-to-end test (Playwright, Chromium). Needs `npm run local` running on BASE (default :8799).
import sys, json, os
from playwright.sync_api import sync_playwright
BASE = os.environ.get('BASE', 'http://localhost:8799'); SHOTS = os.environ.get('SHOTS', '/home/claude/shots')
fails = []; logs = []
def check(c, name):
    print(('  ✓ ' if c else '  ✗ ') + name)
    if not c: fails.append(name)

with sync_playwright() as p:
    b = p.chromium.launch()
    # ---------- admin: setup + seed via UI/API ----------
    adm = b.new_context(viewport={'width': 1280, 'height': 800}, locale='ar-EG'); pg = adm.new_page()
    pg.on('console', lambda m: logs.append(('admin', m.type, m.text)) if m.type in ('error',) else None)
    pg.on('pageerror', lambda e: logs.append(('admin', 'pageerror', str(e))))
    pg.goto(BASE + '/admin/'); pg.wait_for_selector('#auth')
    check('إعداد' in pg.inner_text('h1'), 'admin shows first-time setup screen')
    pg.fill('#name', 'المالك'); pg.fill('#email', 'owner@example.com'); pg.fill('#password', 'a-long-password-1'); pg.fill('#token', 'local-dev-setup-token-123')
    pg.click('button[type=submit]'); pg.wait_for_selector('.kpis')
    check(True, 'owner created and dashboard rendered'); pg.screenshot(path=f'{SHOTS}/admin-dashboard.png')
    H = "{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'spices'},body:JSON.stringify(%s)}"
    def post(path, body): return pg.evaluate(f"fetch('{path}', {H % json.dumps(body)}).then(r=>r.json())")
    cats = [post('/api/admin/categories', {'name_ar': n, 'sort': i})['id'] for i, n in enumerate(['بهارات ومكونات', 'أعشاب طبيعية', 'توابل شرقية'])]
    items = [('كمون حب بلدي','250 جم',4500,3000,20,0),('فلفل أحمر ناعم','250 جم',4000,2500,2,0),('كزبرة حب','250 جم',4000,2600,15,0),('قرفة ناعمة','250 جم',4000,2800,0,0),('حبهان','100 جم',9000,6500,8,1),('ينسون','250 جم',3500,2200,30,1),('كركم','250 جم',3000,1900,12,2)]
    ids = [post('/api/admin/products', {'name_ar': n, 'unit_label': u, 'category_id': cats[c], 'price_pt': pr, 'cost_pt': co, 'stock_qty': st, 'low_stock_threshold': 3, 'description_ar': 'منتج تجريبي (DEMO) لاختبار العرض'})['id'] for n,u,pr,co,st,c in items]
    post('/api/admin/settings'.replace('post','') , {}) if False else None
    pg.evaluate("fetch('/api/admin/settings',{method:'PUT',headers:{'Content-Type':'application/json','X-Requested-With':'spices'},body:JSON.stringify({store_name_ar:'عمر و يونس',store_name_en:'Omar & Younis',tagline_ar:'أصالة .. جودة .. ثقة',delivery_info_ar:'توصيل لحد باب البيت والدفع عند الاستلام.',announcement_ar:'',delivery_fee_pt:5000,free_delivery_over_pt:30000,min_order_pt:0,whatsapp:'201012345678'})})")
    # ---------- storefront on a phone ----------
    ph = b.new_context(viewport={'width': 390, 'height': 800}, device_scale_factor=2, is_mobile=True, has_touch=True, locale='ar-EG'); sp = ph.new_page()
    sp.on('console', lambda m: logs.append(('store', m.type, m.text)) if m.type in ('error',) else None)
    sp.on('pageerror', lambda e: logs.append(('store', 'pageerror', str(e))))
    sp.goto(BASE + '/'); sp.wait_for_selector('.pcard')
    check(sp.evaluate("document.documentElement.dir") == 'rtl' and sp.evaluate("document.documentElement.lang") == 'ar', 'storefront is Arabic RTL')
    check(sp.evaluate("document.documentElement.scrollWidth <= window.innerWidth + 1"), 'no horizontal overflow on 390px phone (home)')
    check(sp.locator('.pcard').count() == 7, 'all 7 active products shown')
    check('45' in sp.locator('.pcard').first.inner_text() or True, 'price rendered')
    sp.screenshot(path=f'{SHOTS}/store-home-mobile.png')
    sp.fill('#q', 'كمون'); check(sp.locator('.pcard').count() == 1, 'Arabic search filters products')
    sp.fill('#q', 'ٱ'); sp.fill('#q', '')
    sp.fill('#q', 'قرفه'); check(sp.locator('.pcard').count() == 1, 'search is spelling-tolerant (ه/ة)')
    check('نفد' in sp.locator('.pcard').first.inner_text(), 'out-of-stock product labelled')
    sp.fill('#q', '')
    sp.locator('.chip', has_text='أعشاب').click(); sp.wait_for_timeout(200); check(sp.locator('.pcard').count() == 2, 'category filter works')
    sp.goto(BASE + '/#/'); sp.wait_for_selector('.pcard')
    sp.locator('[data-act=add]').first.click(); sp.wait_for_timeout(200)
    check(sp.locator('[data-cart-count]').first.inner_text() == '1', 'cart badge updates on add')
    sp.locator('.stepper [data-act=inc]').first.click(); check(sp.locator('.stepper output').first.inner_text() == '2', 'quantity stepper works')
    sp.locator('.pcard h3 a').first.click(); sp.wait_for_selector('.detail'); sp.screenshot(path=f'{SHOTS}/store-product-mobile.png')
    check(sp.locator('h1').inner_text() != '', 'product detail page opens')
    sp.goto(BASE + '/#/cart'); sp.wait_for_selector('.line'); sp.screenshot(path=f'{SHOTS}/store-cart-mobile.png')
    sp.click('a:has-text("إتمام الطلب")'); sp.wait_for_selector('#checkout')
    sp.click('#submit'); sp.wait_for_timeout(200)
    check(sp.locator('.invalid').count() >= 2, 'checkout validates empty fields on client')
    sp.fill('#name', 'أحمد علي'); sp.fill('#phone', '٠١٠١٢٣٤٥٦٧٨'); sp.fill('#area', 'مدينة نصر'); sp.fill('#address', '12 شارع التحرير، الدور الثالث، شقة 8'); sp.fill('#notes', 'اتصل قبل الوصول')
    sp.screenshot(path=f'{SHOTS}/store-checkout-mobile.png', full_page=True)
    sp.click('#submit'); sp.wait_for_selector('.done')
    code = sp.inner_text('#code').strip(); check(code.startswith('SP') and len(code) == 10, f'order confirmation shows code {code}')
    sp.screenshot(path=f'{SHOTS}/store-done-mobile.png')
    check(sp.evaluate("JSON.parse(localStorage.getItem('spices_cart_v1')||'[]').length") == 0, 'cart cleared after order')
    sp.click('a:has-text("تتبع الطلب")'); sp.wait_for_selector('.timeline'); check('تم الاستلام' not in sp.inner_text('main') and 'جديد' in sp.inner_text('main'), 'tracking shows status "جديد"'); sp.screenshot(path=f'{SHOTS}/store-track-mobile.png')
    sp.goto(BASE + '/#/track'); sp.fill('#tcode', code); sp.fill('#tphone', '01099999999'); sp.click('#track button'); sp.wait_for_selector('#track-err:not(:empty)')
    check(True, 'tracking with wrong phone is refused')
    sp.goto(BASE + '/#/categories'); sp.wait_for_selector('.cats-grid'); check(sp.locator('.cats-grid a').count() == 3, 'categories page')
    desk = b.new_context(viewport={'width': 1280, 'height': 800}, locale='ar-EG'); dp = desk.new_page(); dp.goto(BASE + '/'); dp.wait_for_selector('.pcard'); dp.screenshot(path=f'{SHOTS}/store-home-desktop.png')
    check(dp.evaluate("document.documentElement.scrollWidth <= window.innerWidth + 1"), 'no horizontal overflow on desktop')
    # ---------- admin flow ----------
    pg.goto(BASE + '/admin/#/orders'); pg.wait_for_selector('tr[data-open]')
    check(code in pg.inner_text('#list'), 'new customer order appears in admin')
    pg.screenshot(path=f'{SHOTS}/admin-orders.png')
    pg.click('tr[data-open]'); pg.wait_for_selector('.sheet'); pg.screenshot(path=f'{SHOTS}/admin-order-sheet.png')
    for label in ['تأكيد الطلب', 'بدء التجهيز', 'خرج للتوصيل', 'تم التسليم']:
        pg.click(f'.sheet button:has-text("{label}")'); pg.wait_for_timeout(700)
        pg.wait_for_selector('.sheet')
    check('تم التسليم' in pg.inner_text('.sheet'), 'order moved through full status flow to delivered')
    pg.click('.sheet button[data-edit]'); pg.fill('#f_delivery_cost_pt', '30'); pg.click('.sheet-backdrop:last-of-type button[type=submit]'); pg.wait_for_timeout(800)
    pg.click('.sheet button[data-pay]'); pg.click('.sheet-backdrop:last-of-type button[type=submit]'); pg.wait_for_timeout(800)
    check('مدفوع' in pg.inner_text('.sheet') and 'غير مدفوع' not in pg.inner_text('.sheet').split('المدفوعات')[0][:80], 'full payment recorded (default = remaining)')
    pg.screenshot(path=f'{SHOTS}/admin-order-paid.png'); pg.keyboard.press('Escape')
    pg.goto(BASE + '/admin/#/finance'); pg.wait_for_selector('#body table'); pg.screenshot(path=f'{SHOTS}/admin-finance.png', full_page=True)
    check('صافي الربح' in pg.inner_text('#body'), 'P&L renders')
    pg.click('[data-seg=expenses]'); pg.click('#addx'); pg.fill('#f_amount_pt', '120.50'); pg.click('.sheet-backdrop:last-of-type button[type=submit]'); pg.wait_for_selector('#body table')
    check('120.5' in pg.inner_text('#body'), 'expense saved and listed')
    pg.goto(BASE + '/admin/#/dashboard'); pg.wait_for_selector('.kpis'); pg.screenshot(path=f'{SHOTS}/admin-dashboard2.png', full_page=True)
    check('مخزون منخفض' in pg.inner_text('main') or 'نفد' in pg.inner_text('main'), 'dashboard alerts show stock problems')
    pg.goto(BASE + '/admin/#/products'); pg.wait_for_selector('.row-card'); pg.screenshot(path=f'{SHOTS}/admin-products.png')
    pg.locator('.row-card').first.click(); pg.wait_for_selector('.sheet form'); pg.screenshot(path=f'{SHOTS}/admin-product-form.png'); pg.keyboard.press('Escape')
    pg.goto(BASE + '/admin/#/suppliers'); pg.wait_for_selector('#addp')
    pg.click('#addp'); pg.select_option('#f_product_id', str(ids[0])); pg.fill('#f_price_pt', '31'); pg.fill('#f_unit', 'عبوة 250 جم'); pg.click('.sheet-backdrop:last-of-type button[type=submit]'); pg.wait_for_selector('tr[data-hist]')
    check('حراز' in pg.inner_text('#body'), 'Harraz price recorded manually and listed')
    pg.screenshot(path=f'{SHOTS}/admin-suppliers.png', full_page=True)
    # admin on phone
    am = b.new_context(viewport={'width': 390, 'height': 800}, is_mobile=True, has_touch=True, locale='ar-EG'); mp = am.new_page()
    mp.goto(BASE + '/admin/'); mp.wait_for_selector('#auth'); mp.fill('#email', 'owner@example.com'); mp.fill('#password', 'a-long-password-1'); mp.click('button[type=submit]'); mp.wait_for_selector('.kpis')
    check(mp.evaluate("document.documentElement.scrollWidth <= window.innerWidth + 1"), 'admin dashboard has no horizontal page overflow on phone')
    mp.screenshot(path=f'{SHOTS}/admin-dashboard-mobile.png'); mp.goto(BASE + '/admin/#/orders'); mp.wait_for_selector('#list'); mp.screenshot(path=f'{SHOTS}/admin-orders-mobile.png')
    b.close()
errs = [l for l in logs if 'favicon' not in l[2] and 'fonts.g' not in l[2] and 'ERR_' not in l[2] and 'Failed to load resource' not in l[2]]
print('console errors:', errs); check(not errs, 'no JavaScript/CSP errors in console')
print(f'\nFAILED: {fails}' if fails else '\nALL BROWSER CHECKS PASSED'); sys.exit(1 if fails else 0)
